import React, { useEffect, useState } from "react";
import { motion } from "framer-motion";

const WorkerSplash = ({ onComplete }) => {
  const [isImploding, setIsImploding] = useState(false);
  const [glitch, setGlitch] = useState(false);

  useEffect(() => {
    // Random glitch flickers for that "unstable OS" vibe
    const glitchInterval = setInterval(() => setGlitch(prev => !prev), 150);

    const transitionTimer = setTimeout(() => setIsImploding(true), 3000);
    const completeTimer = setTimeout(onComplete, 3700);

    return () => { 
      clearInterval(glitchInterval);
      clearTimeout(transitionTimer); 
      clearTimeout(completeTimer); 
    };
  }, [onComplete]);

  return (
    <div className="h-screen w-full bg-[#030303] flex items-center justify-center overflow-hidden font-mono">

      {/* 1. DARK OVERLAY: CRT Scanlines */}
      <div className="absolute inset-0 pointer-events-none z-50 bg-[linear-gradient(rgba(18,16,16,0)_50%,rgba(0,0,0,0.2)_50%)] bg-[length:100%_2px]" />

      <div className={`${isImploding ? "animate-void" : ""}`}>
        <div className="flex flex-col items-center">

          <div className="flex gap-2 text-white font-black text-7xl md:text-9xl tracking-tight">
            {/* Letter T */}
            <motion.span 
              initial={{ opacity: 0, scale: 2 }}
              animate={{ opacity: 1, scale: 1 }}
              transition={{ duration: 0.1, delay: 0.8 }}
              className={glitch ? "glitch-active" : ""}
            >
              T
            </motion.span>

            {/* The 2 (The only color point) */}
            <motion.span 
              initial={{ opacity: 0, y: -20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.05, delay: 1.2 }}
              className="text-[#CAD23C]"
            >
              2
            </motion.span>

            {/* Letter T */}
            <motion.span 
              initial={{ opacity: 0, scale: 0.5 }}
              animate={{ opacity: 1, scale: 1 }}
              transition={{ duration: 0.1, delay: 1.0 }}
            >
              T
            </motion.span>
          </div>

          {/* Tactical Status Codes */}
          <div className="mt-8 flex flex-col items-center space-y-1">
             <motion.div 
               initial={{ width: 0 }} animate={{ width: "200px" }}
               transition={{ duration: 2, delay: 1.2 }}
               className="h-[1px] bg-white/20"
             />
             <div className="text-[9px] text-[#CAD23C] tracking-[1em] opacity-50 overflow-hidden whitespace-nowrap">
                {glitch ? "SECURE_LINK_ENCRYPTED" : "ESTABLISHING_V4_NODE"}
             </div>
          </div>
        </div>
      </div>

      {/* Background Ambience: One single glowing pixel moving slowly */}
      <motion.div 
        animate={{ 
          x: [0, 100, -100, 0], 
          y: [0, -50, 50, 0],
          opacity: [0, 1, 0] 
        }}
        transition={{ duration: 10, repeat: Infinity }}
        className="absolute w-1 h-1 bg-[#CAD23C] blur-sm shadow-[0_0_10px_#CAD23C]"
      />
    </div>
  );
};

export default WorkerSplash;
